#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-06

# Test: scripts/audit-skill-claims.mjs must not report a clean sweep when it
# could not look the issues up.
#
# Why (gate-fault-arm audit, docs/audits/gate-fault-arm-audit-2026-09-06.md):
#
# The script asks `gh api` for each cited issue's state. A lookup that failed
# (no token, rate limit, network) used to become state "unknown", which the
# stale filter read as "not closed", so a run in which EVERY gh call failed
# emitted `stale: []`. skill-claims-audit.yml then wrote stale=0 and commented
# "Sweep is clean as of this run" on the rolling report issue. Measured in the
# audit: gh stub returning closed -> stale 1, exit 1; gh stub failing -> stale
# 0, exit 0. Same shape as #3933: an empty array byte-identical to a triaged
# one.
#
# Arms:
#   control: gh answers closed          -> stale 1, exit 1 (the gate fires)
#   control2: gh answers open           -> stale 0, unresolved 0, exit 0
#   fault:   gh fails on every call     -> stale 0, unresolved 1, exit 2
#   fault2:  zero files under src/      -> scanned 0, exit 2
# Then the workflow's consumer lines are replayed on the fault JSON and on an
# EMPTY claims file, asserting neither yields the "clean" pair (stale=0 AND
# unresolved=0).

set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"

echo "=== audit-skill-claims blind-sweep gate ==="
echo ""

WORK="$(mktemp -d "${TMPDIR:-/tmp}/ork-claims-blind.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT

PASS=0; FAIL=0
ok()  { echo "  PASS: $1"; PASS=$((PASS + 1)); }
bad() { echo "  FAIL: $1"; FAIL=$((FAIL + 1)); }

# Fixture tree: the script resolves ROOT from its own location (../), so it is
# copied to <fixture>/scripts/ and reads <fixture>/src/{skills,agents}.
FX="$WORK/fx"
mkdir -p "$FX/scripts" "$FX/src/skills/x" "$FX/bin-closed" "$FX/bin-open" "$FX/bin-fail"
cp "$REPO_ROOT/scripts/audit-skill-claims.mjs" "$FX/scripts/"
printf 'Intro.\nSee #1234 for the migration that is pending.\n' > "$FX/src/skills/x/SKILL.md"

cat > "$FX/bin-closed/gh" <<'EOF'
#!/usr/bin/env bash
echo '{"state":"closed","pr":false}'
EOF
cat > "$FX/bin-open/gh" <<'EOF'
#!/usr/bin/env bash
echo '{"state":"open","pr":false}'
EOF
cat > "$FX/bin-fail/gh" <<'EOF'
#!/usr/bin/env bash
echo "gh: HTTP 401: Bad credentials" >&2
exit 1
EOF
chmod +x "$FX"/bin-*/gh

run_with() { # <bin-dir> <out-file>; prints rc; stderr kept in <out-file>.err
  local rc=0
  ( cd "$FX" && PATH="$FX/$1:$PATH" node scripts/audit-skill-claims.mjs --json > "$2" 2> "$2.err" ) || rc=$?
  echo "$rc"
}

# control: closed -> stale 1, exit 1
rc=$(run_with bin-closed "$WORK/closed.json")
stale=$(jq '.stale | length' "$WORK/closed.json")
if [[ "$rc" == "1" && "$stale" == "1" ]]; then
  ok "control: gh says closed -> stale=1, exit 1"
else
  bad "control: gh says closed -> got stale=$stale exit $rc (want 1 / 1)"
fi

# control2: open -> stale 0, unresolved 0, exit 0
rc=$(run_with bin-open "$WORK/open.json")
stale=$(jq '.stale | length' "$WORK/open.json"); unres=$(jq '.unresolved' "$WORK/open.json")
if [[ "$rc" == "0" && "$stale" == "0" && "$unres" == "0" ]]; then
  ok "control2: gh says open -> stale=0, unresolved=0, exit 0"
else
  bad "control2: gh says open -> got stale=$stale unresolved=$unres exit $rc"
fi

# fault: gh fails -> stale 0, unresolved 1, exit 2
rc=$(run_with bin-fail "$WORK/fail.json")
stale=$(jq '.stale | length' "$WORK/fail.json"); unres=$(jq '.unresolved' "$WORK/fail.json")
if [[ "$rc" == "2" && "$stale" == "0" && "$unres" == "1" ]]; then
  ok "fault: gh fails -> stale=0, unresolved=1, exit 2 (blind, not clean)"
else
  bad "fault: gh fails -> got stale=$stale unresolved=$unres exit $rc (want 0 / 1 / 2)"
fi

# fault2: zero files scanned -> exit 2
rm -rf "$FX/src/skills"; mkdir -p "$FX/src/skills"
rc=$(run_with bin-closed "$WORK/empty-tree.json")
scanned=$(jq '.scanned' "$WORK/empty-tree.json")
if [[ "$rc" == "2" && "$scanned" == "0" ]]; then
  ok "fault2: zero files scanned -> exit 2"
else
  bad "fault2: zero files scanned -> got scanned=$scanned exit $rc (want 0 / 2)"
fi

# Replay the workflow's consumer on the fault JSON and on an empty file. jq's
# stderr goes to a scratch file: an unparseable claims file is the case under
# test, and the EMPTY stdout it produces is the value the branch reads.
consumer() { # <claims-file>; prints "stale unresolved"
  local STALE UNRESOLVED SCANNED
  STALE=$(jq -r '.stale | length' "$1" 2>> "$WORK/consumer.err")
  UNRESOLVED=$(jq -r '.unresolved // 0' "$1" 2>> "$WORK/consumer.err")
  SCANNED=$(jq -r '.scanned // 0' "$1" 2>> "$WORK/consumer.err")
  if [ -z "$STALE" ] || [ -z "$UNRESOLVED" ]; then STALE=0; UNRESOLVED=1; SCANNED=0; fi
  if [ "$SCANNED" = "0" ]; then UNRESOLVED=$((UNRESOLVED + 1)); fi
  echo "$STALE $UNRESOLVED"
}
read -r s u < <(consumer "$WORK/fail.json")
if [[ "$s" == "0" && "$u" != "0" ]]; then
  ok "workflow consumer: gh-failed JSON -> stale=$s unresolved=$u (never 'clean')"
else
  bad "workflow consumer: gh-failed JSON -> stale=$s unresolved=$u would read as clean"
fi
: > "$WORK/empty.json"
read -r s u < <(consumer "$WORK/empty.json")
if [[ "$u" != "0" ]]; then
  ok "workflow consumer: EMPTY claims file -> unresolved=$u (never 'clean')"
else
  bad "workflow consumer: EMPTY claims file -> stale=$s unresolved=$u would read as clean"
fi

# The shipped workflow must carry the same consumer logic this test replays.
WF="$REPO_ROOT/.github/workflows/skill-claims-audit.yml"
if grep -q "unresolved == '0'" "$WF" && grep -q "jq -r '.unresolved // 0'" "$WF"; then
  ok "skill-claims-audit.yml gates 'clean' on unresolved == 0"
else
  bad "skill-claims-audit.yml no longer gates 'clean' on unresolved == 0"
fi

echo ""
echo "Results: $PASS passed, $FAIL failed"
[[ $FAIL -eq 0 ]]
